//! HTTP routing for the kvhttp API.

use std::sync::Arc;

use axum::body::{self, Body, Bytes};
use axum::extract::{Request, State};
use axum::http::{Method, StatusCode, header};
use axum::response::{IntoResponse, Response};

use crate::store::{PutOutcome, Store};

/// Largest value accepted by `PUT /kv/<key>`.
pub const MAX_VALUE_BYTES: usize = 1024 * 1024;

const MAX_KEY_LEN: usize = 64;

/// Builds the application router backed by `store`.
pub fn router(store: Arc<Store>) -> axum::Router {
    axum::Router::new().fallback(dispatch).with_state(store)
}

async fn dispatch(State(store): State<Arc<Store>>, req: Request) -> Response {
    let (parts, body) = req.into_parts();
    let path = parts.uri.path();
    let method = parts.method;

    match path {
        "/health" => health(&method),
        "/kv" => list(&store, &method),
        _ => match path.strip_prefix("/kv/") {
            Some(key) => item(&store, &method, key, body).await,
            None => StatusCode::NOT_FOUND.into_response(),
        },
    }
}

fn is_valid_key(key: &str) -> bool {
    (1..=MAX_KEY_LEN).contains(&key.len())
        && key
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

fn health(method: &Method) -> Response {
    if method == Method::GET {
        (StatusCode::OK, "ok").into_response()
    } else {
        StatusCode::METHOD_NOT_ALLOWED.into_response()
    }
}

fn list(store: &Store, method: &Method) -> Response {
    if method != Method::GET {
        return StatusCode::METHOD_NOT_ALLOWED.into_response();
    }
    // Keys are restricted to `[A-Za-z0-9_-]`, so they never need escaping.
    let keys = store.keys();
    let mut json = String::with_capacity(2 + keys.iter().map(|k| k.len() + 3).sum::<usize>());
    json.push('[');
    for (i, key) in keys.iter().enumerate() {
        if i > 0 {
            json.push(',');
        }
        json.push('"');
        json.push_str(key);
        json.push('"');
    }
    json.push(']');
    ([(header::CONTENT_TYPE, "application/json")], json).into_response()
}

async fn item(store: &Store, method: &Method, key: &str, body: Body) -> Response {
    if !is_valid_key(key) {
        return StatusCode::BAD_REQUEST.into_response();
    }
    match *method {
        Method::GET => match store.get(key) {
            Some(value) => (
                [(header::CONTENT_TYPE, "application/octet-stream")],
                value,
            )
                .into_response(),
            None => StatusCode::NOT_FOUND.into_response(),
        },
        Method::PUT => {
            let value: Bytes = match body::to_bytes(body, MAX_VALUE_BYTES).await {
                Ok(value) => value,
                Err(_) => return StatusCode::PAYLOAD_TOO_LARGE.into_response(),
            };
            match store.put(key, value) {
                PutOutcome::Created => StatusCode::CREATED,
                PutOutcome::Replaced => StatusCode::OK,
            }
            .into_response()
        }
        Method::DELETE => {
            if store.delete(key) {
                StatusCode::NO_CONTENT.into_response()
            } else {
                StatusCode::NOT_FOUND.into_response()
            }
        }
        _ => StatusCode::METHOD_NOT_ALLOWED.into_response(),
    }
}

#[cfg(test)]
mod tests {
    use super::is_valid_key;

    #[test]
    fn key_validation() {
        assert!(is_valid_key("a"));
        assert!(is_valid_key("A-z_09"));
        assert!(is_valid_key(&"k".repeat(64)));
        assert!(!is_valid_key(""));
        assert!(!is_valid_key(&"k".repeat(65)));
        assert!(!is_valid_key("a/b"));
        assert!(!is_valid_key("bad.key"));
        assert!(!is_valid_key("%41"));
    }
}

//! kvhttp: an in-memory HTTP/1.1 key-value server.

mod handler;
mod store;

use std::net::{Ipv4Addr, SocketAddr};
use std::process::ExitCode;
use std::sync::Arc;

use tokio::net::TcpListener;

use crate::store::Store;

fn parse_port() -> Option<u16> {
    let mut args = std::env::args().skip(1);
    let port = args.next()?.parse::<u16>().ok()?;
    (args.next().is_none() && port != 0).then_some(port)
}

#[tokio::main]
async fn main() -> ExitCode {
    let Some(port) = parse_port() else {
        eprintln!("usage: app <port>");
        return ExitCode::from(2);
    };

    let addr = SocketAddr::from((Ipv4Addr::LOCALHOST, port));
    let listener = match TcpListener::bind(addr).await {
        Ok(listener) => listener,
        Err(err) => {
            eprintln!("failed to bind {addr}: {err}");
            return ExitCode::FAILURE;
        }
    };

    let app = handler::router(Arc::new(Store::new()));
    if let Err(err) = axum::serve(listener, app).await {
        eprintln!("server error: {err}");
        return ExitCode::FAILURE;
    }
    ExitCode::SUCCESS
}

//! Thread-safe in-memory key-value store. Keys are kept sorted so listing
//! is a cheap traversal.

use std::collections::BTreeMap;
use std::sync::{PoisonError, RwLock};

use axum::body::Bytes;

/// Outcome of a [`Store::put`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PutOutcome {
    Created,
    Replaced,
}

#[derive(Debug, Default)]
pub struct Store {
    entries: RwLock<BTreeMap<String, Bytes>>,
}

impl Store {
    pub fn new() -> Self {
        Self::default()
    }

    /// Stores `value` under `key`, reporting whether the key was new.
    pub fn put(&self, key: &str, value: Bytes) -> PutOutcome {
        let mut entries = self.entries.write().unwrap_or_else(PoisonError::into_inner);
        match entries.insert(key.to_owned(), value) {
            Some(_) => PutOutcome::Replaced,
            None => PutOutcome::Created,
        }
    }

    /// Returns the value stored under `key`, if any.
    pub fn get(&self, key: &str) -> Option<Bytes> {
        let entries = self.entries.read().unwrap_or_else(PoisonError::into_inner);
        entries.get(key).cloned()
    }

    /// Removes `key`, returning whether it was present.
    pub fn delete(&self, key: &str) -> bool {
        let mut entries = self.entries.write().unwrap_or_else(PoisonError::into_inner);
        entries.remove(key).is_some()
    }

    /// Returns all keys in ascending order.
    pub fn keys(&self) -> Vec<String> {
        let entries = self.entries.read().unwrap_or_else(PoisonError::into_inner);
        entries.keys().cloned().collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn put_get_delete_list() {
        let store = Store::new();
        assert_eq!(store.put("b", Bytes::from_static(b"2")), PutOutcome::Created);
        assert_eq!(store.put("a", Bytes::from_static(b"1")), PutOutcome::Created);
        assert_eq!(store.put("a", Bytes::from_static(b"x")), PutOutcome::Replaced);
        assert_eq!(store.get("a").as_deref(), Some(&b"x"[..]));
        assert_eq!(store.keys(), ["a", "b"]);
        assert!(store.delete("a"));
        assert!(!store.delete("a"));
        assert_eq!(store.get("a"), None);
    }
}
